package com.queryx.database.entities;
import jakarta.persistence.*; import java.time.OffsetDateTime; import java.util.UUID;
@Entity @Table(name="users") public class User { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(nullable=false,unique=true,length=100) private String username; @Column(name="display_name",nullable=false,length=200) private String displayName; @Column(nullable=false,unique=true,length=320) private String email; @Column(name="created_at",nullable=false) private OffsetDateTime createdAt; public UUID getId(){return id;} public String getUsername(){return username;} public void setUsername(String v){username=v;} public String getDisplayName(){return displayName;} public void setDisplayName(String v){displayName=v;} public String getEmail(){return email;} public void setEmail(String v){email=v;} }
